mapper.select:
SELECT ID as id, date, sentimentScore, rollingAverage,
       rollingStandardDeviation, sampleCount
FROM ${table}
WHERE date = #{date}
ORDER BY ID DESC
LIMIT 1

SELECT ID as id, date, sentimentScore, rollingAverage,
       rollingStandardDeviation, sampleCount
FROM ${table}
WHERE date >= #{fromDate}
ORDER BY date ASC, ID ASC

mapper.insert:
